const a = msg.payload.acceleration;
const m = msg.payload.magnetic;
const h = msg.payload.heading;

// Roll and pitch from the gravity vector (same convention as the tilt-compensated heading).
const roll  = Math.atan2(a.y, a.z);
const pitch = Math.atan2(-a.x, a.y * Math.sin(roll) + a.z * Math.cos(roll));

const names = ['N','NNE','NE','ENE','E','ESE','SE','SSE','S','SSW','SW','WSW','W','WNW','NW','NNW'];
const point = names[Math.round(h / 22.5) % 16];

const field = Math.sqrt(m.x * m.x + m.y * m.y + m.z * m.z);

msg.payload = {
    heading_deg: Math.round(h * 10) / 10,
    compass: point,
    pitch_deg: Math.round(pitch * 180 / Math.PI * 10) / 10,
    roll_deg: Math.round(roll * 180 / Math.PI * 10) / 10,
    field_uT: Math.round(field * 10) / 10,
    temperature_delta_C: msg.payload.temperature_delta
};
return msg;
